INSERT INTO "norfolk_vote_enrichment" VALUES(395,'An Ordinance to Amend and Reordain the Capital Improvement Plan Budget for FY2025 to Reappropriate Previously Authorized Bonds.','This ordinance updated the Capital Improvement Plan (CIP) budget for Fiscal Year 2025 to reallocate funds from previously authorized bonds. This means money already approved for projects is being reassigned to different capital projects.','budget','["capital improvement funding", "municipal bond reappropriation", "local government finance"]','[]','2026-06-20 05:09:07');
