-- Norfolk City Council seed (auto-generated from local polls.db)
-- Loaded idempotently by build.sh. Additive only.
BEGIN TRANSACTION;

-- norfolk_council_votes
DROP TABLE IF EXISTS "norfolk_council_votes";
CREATE TABLE norfolk_council_votes (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            meeting_id      INTEGER NOT NULL,
            meeting_date    TEXT,
            agenda_item     TEXT,
            title           TEXT,
            motion          TEXT,
            moved_by        TEXT,
            seconded_by     TEXT,
            result          TEXT,
            vote_count      TEXT,
            votes_json      TEXT,       -- JSON object {member: vote}
            scraped_at      TEXT DEFAULT (datetime('now'))
        , category TEXT);

-- norfolk_council_member_votes
DROP TABLE IF EXISTS "norfolk_council_member_votes";
CREATE TABLE norfolk_council_member_votes (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            vote_id         INTEGER NOT NULL REFERENCES norfolk_council_votes(id),
            meeting_id      INTEGER NOT NULL,
            meeting_date    TEXT,
            member_name     TEXT,
            vote            TEXT,       -- yes / no / abstain / absent
            agenda_item     TEXT,
            title           TEXT,
            result          TEXT
        , category TEXT);

-- norfolk_vote_enrichment
DROP TABLE IF EXISTS "norfolk_vote_enrichment";
CREATE TABLE norfolk_vote_enrichment (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            title           TEXT UNIQUE NOT NULL,
            plain_english   TEXT,
            topic           TEXT,
            state_tags      TEXT,   -- JSON array
            federal_tags    TEXT,   -- JSON array
            enriched_at     TEXT DEFAULT (datetime('now'))
        );

-- norfolk_council_testimony
DROP TABLE IF EXISTS "norfolk_council_testimony";
CREATE TABLE norfolk_council_testimony (
            id           INTEGER PRIMARY KEY AUTOINCREMENT,
            meeting_date TEXT,
            agenda_item  TEXT,
            speaker_name TEXT,
            speaker_addr TEXT,
            stance       TEXT,  -- oppose | support | present | comment
            note         TEXT,
            scraped_at   TEXT DEFAULT (datetime('now'))
        , ward INTEGER, superward INTEGER, lat REAL, lon REAL, geocode_source TEXT);

-- norfolk_finance_totals
DROP TABLE IF EXISTS "norfolk_finance_totals";
CREATE TABLE norfolk_finance_totals (
            id           INTEGER PRIMARY KEY AUTOINCREMENT,
            member_name  TEXT NOT NULL,
            sector       TEXT NOT NULL,
            total_amount REAL,
            donor_count  INTEGER,
            pct_of_total REAL,
            updated_at   TEXT DEFAULT (datetime('now')),
            UNIQUE(member_name, sector)
        );

-- norfolk_finance_summary
DROP TABLE IF EXISTS "norfolk_finance_summary";
CREATE TABLE norfolk_finance_summary (
            member_name  TEXT PRIMARY KEY,
            total_raised REAL,
            top_sector   TEXT,
            top_sector_amt  REAL,
            top_sector_pct  REAL,
            sector_json  TEXT,   -- [{sector, total_amount, pct_of_total, donor_count}]
            updated_at   TEXT DEFAULT (datetime('now'))
        );

-- norfolk_donor_vote_adjacency
DROP TABLE IF EXISTS "norfolk_donor_vote_adjacency";
CREATE TABLE norfolk_donor_vote_adjacency (
            id               INTEGER PRIMARY KEY AUTOINCREMENT,
            member_name      TEXT NOT NULL,
            sector           TEXT NOT NULL,
            sector_pct       REAL,
            sector_amt       REAL,
            topic            TEXT NOT NULL,
            member_yes_pct   REAL,
            council_yes_pct  REAL,
            delta_pp         REAL,
            topic_vote_count INTEGER,
            updated_at       TEXT DEFAULT (datetime('now')),
            UNIQUE(member_name, sector, topic)
        );

-- norfolk_donor_vote_summary
DROP TABLE IF EXISTS "norfolk_donor_vote_summary";
CREATE TABLE norfolk_donor_vote_summary (
            member_name       TEXT NOT NULL,
            sector            TEXT NOT NULL,
            sector_pct        REAL,
            sector_amt        REAL,
            top_topic         TEXT,
            top_topic_delta   REAL,
            top_topic_yes_pct REAL,
            council_yes_pct   REAL,
            topic_vote_count  INTEGER,
            signal_text       TEXT,
            updated_at        TEXT DEFAULT (datetime('now')),
            PRIMARY KEY (member_name, sector)
        );

-- norfolk_member_dissent
DROP TABLE IF EXISTS "norfolk_member_dissent";
CREATE TABLE norfolk_member_dissent (
            id               INTEGER PRIMARY KEY AUTOINCREMENT,
            member_name      TEXT NOT NULL,
            topic            TEXT NOT NULL,
            member_no_pct    REAL,
            council_no_pct   REAL,
            delta_pp         REAL,
            member_no_count  INTEGER,
            topic_vote_count INTEGER,
            updated_at       TEXT DEFAULT (datetime('now')),
            UNIQUE(member_name, topic)
        );

-- norfolk_voting_blocs
DROP TABLE IF EXISTS "norfolk_voting_blocs";
CREATE TABLE norfolk_voting_blocs (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            member_a        TEXT NOT NULL,
            member_b        TEXT NOT NULL,
            agreement_pct   REAL,
            shared_votes    INTEGER,
            agree_count     INTEGER,
            updated_at      TEXT DEFAULT (datetime('now')),
            UNIQUE(member_a, member_b)
        );

-- norfolk_upcoming_agenda
DROP TABLE IF EXISTS "norfolk_upcoming_agenda";
CREATE TABLE norfolk_upcoming_agenda (
            id           INTEGER PRIMARY KEY AUTOINCREMENT,
            meeting_id   INTEGER NOT NULL,
            meeting_date TEXT NOT NULL,
            item_ref     TEXT,
            title        TEXT,
            status       TEXT DEFAULT 'scheduled',
            agenda_url   TEXT,
            scraped_at   TEXT DEFAULT (datetime('now')),
            UNIQUE(meeting_id, item_ref)
        );
COMMIT;
